@@ imports @@
-import { Given, Then } from "@cucumber/cucumber";
 import { expect } from "@playwright/test";
+import path from "node:path";
+import { pathToFileURL } from "node:url";
+
+const managedCucumberBinary = process.env.APPRAISE_CUCUMBER_BINARY;
+const cucumberModule = managedCucumberBinary
+  ? pathToFileURL(path.resolve(path.dirname(managedCucumberBinary), "../lib/index.js")).href
+  : "@cucumber/cucumber";
+const { Given, Then } = (await import(cucumberModule)) as typeof import("@cucumber/cucumber");
